--
-- Table structure for table `global_equipment`
--

DROP TABLE IF EXISTS `global_equipment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `global_equipment` (
  `item_barcode` varchar(64) NOT NULL,
  `brand_model` varchar(100) NOT NULL,
  `purchase_date` date NOT NULL,
  `unit_cost_usd` decimal(8,2) NOT NULL,
  `current_status` enum('Operational','Under Repair','Needs Inspection','In Central Warehouse') NOT NULL,
  `school_id` int DEFAULT NULL,
  `shipping_date` date DEFAULT NULL,
  PRIMARY KEY (`item_barcode`),
  KEY `fk_equipment_school` (`school_id`),
  CONSTRAINT `fk_equipment_school` FOREIGN KEY (`school_id`) REFERENCES `schools` (`school_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `chk_shipping_after_purchase` CHECK (((`shipping_date` is null) or (`shipping_date` >= `purchase_date`))),
  CONSTRAINT `global_equipment_chk_1` CHECK ((`unit_cost_usd` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

