--
-- Table structure for table `maintenance_logs`
--

DROP TABLE IF EXISTS `maintenance_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `maintenance_logs` (
  `field_id` int NOT NULL,
  `log_date` date NOT NULL,
  `performed_by` varchar(100) NOT NULL,
  `maintenance_cost` decimal(8,2) NOT NULL,
  `work_summary` varchar(255) NOT NULL,
  `safety_passed` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`field_id`,`log_date`),
  CONSTRAINT `fk_maintenance_field` FOREIGN KEY (`field_id`) REFERENCES `fields` (`field_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `maintenance_logs_chk_1` CHECK ((`maintenance_cost` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

