--
-- Table structure for table `match_events`
--

DROP TABLE IF EXISTS `match_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `match_events` (
  `event_id` int NOT NULL AUTO_INCREMENT,
  `match_id` int NOT NULL,
  `student_id` varchar(10) NOT NULL,
  `minute_in_game` int NOT NULL,
  `event_type` enum('Goal','Yellow Card','Red Card','Assist','Substitution') NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`event_id`),
  KEY `fk_events_match` (`match_id`),
  KEY `fk_events_student` (`student_id`),
  KEY `idx_events_type_student` (`event_type`,`student_id`),
  CONSTRAINT `fk_events_match` FOREIGN KEY (`match_id`) REFERENCES `matches` (`match_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_events_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`student_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `match_events_chk_1` CHECK ((`minute_in_game` between 1 and 120))
) ENGINE=InnoDB AUTO_INCREMENT=1265 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

