--
-- Table structure for table `matches`
--

DROP TABLE IF EXISTS `matches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `matches` (
  `match_id` int NOT NULL AUTO_INCREMENT,
  `home_team_id` int NOT NULL,
  `away_team_id` int NOT NULL,
  `field_id` int NOT NULL,
  `match_date` date NOT NULL,
  `start_time` time NOT NULL,
  `home_score` int NOT NULL DEFAULT '0',
  `away_score` int NOT NULL DEFAULT '0',
  `match_status` enum('Completed','Scheduled','Postponed','In Progress') NOT NULL,
  `round_stage` enum('Round 1','Round 2','Round 3','Quarter Final','Semi Final','Final') NOT NULL,
  `referee_name` varchar(100) NOT NULL,
  PRIMARY KEY (`match_id`),
  KEY `fk_matches_home_team` (`home_team_id`),
  KEY `fk_matches_away_team` (`away_team_id`),
  KEY `fk_matches_field` (`field_id`),
  KEY `idx_matches_stage_status_date` (`round_stage`,`match_status`,`match_date`),
  CONSTRAINT `fk_matches_away_team` FOREIGN KEY (`away_team_id`) REFERENCES `teams` (`team_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_matches_field` FOREIGN KEY (`field_id`) REFERENCES `fields` (`field_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_matches_home_team` FOREIGN KEY (`home_team_id`) REFERENCES `teams` (`team_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_different_teams` CHECK ((`home_team_id` <> `away_team_id`)),
  CONSTRAINT `chk_match_max_score_cap` CHECK (((`home_score` between 0 and 25) and (`away_score` between 0 and 25))),
  CONSTRAINT `matches_chk_1` CHECK ((`home_score` >= 0)),
  CONSTRAINT `matches_chk_2` CHECK ((`away_score` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

