--
-- Table structure for table `practices`
--

DROP TABLE IF EXISTS `practices`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `practices` (
  `practice_id` int NOT NULL AUTO_INCREMENT,
  `team_id` int NOT NULL,
  `field_id` int NOT NULL,
  `practice_date` date NOT NULL,
  `start_time` time NOT NULL,
  `duration_minutes` int NOT NULL,
  `practice_topic` varchar(100) NOT NULL,
  PRIMARY KEY (`practice_id`),
  KEY `fk_practices_team` (`team_id`),
  KEY `fk_practices_field` (`field_id`),
  CONSTRAINT `fk_practices_field` FOREIGN KEY (`field_id`) REFERENCES `fields` (`field_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_practices_team` FOREIGN KEY (`team_id`) REFERENCES `teams` (`team_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_min_practice_duration` CHECK ((`duration_minutes` >= 40)),
  CONSTRAINT `practices_chk_1` CHECK ((`duration_minutes` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

