DROP TABLE IF EXISTS `price_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `price_history` (
  `history_id` int NOT NULL,
  `recorded_price` decimal(10,2) NOT NULL,
  `player_id` varchar(20) NOT NULL,
  `round_id` int NOT NULL,
  PRIMARY KEY (`history_id`),
  KEY `fk_price_student` (`player_id`),
  KEY `fk_price_round` (`round_id`),
  CONSTRAINT `fk_price_round` FOREIGN KEY (`round_id`) REFERENCES `rounds` (`round_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_price_student` FOREIGN KEY (`player_id`) REFERENCES `students` (`student_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

