--
-- Table structure for table `students`
--

DROP TABLE IF EXISTS `students`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `students` (
  `student_id` varchar(10) NOT NULL,
  `first_name` varchar(50) NOT NULL,
  `last_name` varchar(50) NOT NULL,
  `birth_date` date NOT NULL,
  `school_id` int NOT NULL,
  `preferred_position` enum('Goalkeeper','Defender','Midfielder','Forward') NOT NULL,
  `strong_foot` enum('Right','Left','Both') NOT NULL,
  `join_date` date NOT NULL,
  `technical_rating` int NOT NULL,
  `current_price` decimal(10,2) DEFAULT '50.00',
  `mental_rating` int NOT NULL,
  PRIMARY KEY (`student_id`),
  KEY `fk_students_school` (`school_id`),
  KEY `idx_students_pos_rating` (`preferred_position`,`technical_rating`),
  CONSTRAINT `fk_students_school` FOREIGN KEY (`school_id`) REFERENCES `schools` (`school_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `students_chk_1` CHECK ((`technical_rating` between 1 and 100)),
  CONSTRAINT `students_chk_2` CHECK ((`mental_rating` between 1 and 100))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

