DROP TABLE IF EXISTS `teams`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `teams` (
  `team_id` int NOT NULL AUTO_INCREMENT,
  `team_name` varchar(100) NOT NULL,
  `school_id` int NOT NULL,
  `captain_student_id` varchar(10) NOT NULL,
  `age_group` enum('U12','U14','U16','U18') NOT NULL,
  `established_year` int NOT NULL,
  PRIMARY KEY (`team_id`),
  UNIQUE KEY `captain_student_id` (`captain_student_id`),
  UNIQUE KEY `uq_school_team_name` (`school_id`,`team_name`),
  CONSTRAINT `fk_teams_captain` FOREIGN KEY (`captain_student_id`) REFERENCES `students` (`student_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_teams_school` FOREIGN KEY (`school_id`) REFERENCES `schools` (`school_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `teams_chk_1` CHECK ((`established_year` between 1900 and 2026))
) ENGINE=InnoDB AUTO_INCREMENT=501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
